import Foundation

/// The bundled, searchable list of verified NOAA tide-prediction stations.
/// Generated by `swift run catalog-builder` from the CO-OPS Metadata API
/// (`stations.json?type=tidepredictions`), filtered to supported US geography.
public struct StationCatalog: Sendable {
    public struct File: Codable, Sendable {
        public let generatedAt: Date
        public let source: String
        public let stations: [TideStation]

        public init(generatedAt: Date, source: String, stations: [TideStation]) {
            self.generatedAt = generatedAt
            self.source = source
            self.stations = stations
        }
    }

    public let generatedAt: Date
    public let stations: [TideStation]
    private let byID: [String: TideStation]
    private let searchKeys: [String: String]

    public init(file: File) {
        generatedAt = file.generatedAt
        stations = file.stations
        byID = Dictionary(file.stations.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
        searchKeys = Dictionary(
            file.stations.map { ($0.id, Self.searchKey(for: $0)) },
            uniquingKeysWith: { first, _ in first }
        )
    }

    /// Loads the catalog bundled with TideKit.
    public static func bundled() throws -> StationCatalog {
        guard let url = Bundle.module.url(forResource: "stations", withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        return StationCatalog(file: try decoder.decode(File.self, from: Data(contentsOf: url)))
    }

    public func station(id: String) -> TideStation? { byID[id] }

    /// Matches every query word against station name, state code/name and ID.
    /// Results are ranked: exact ID, then name prefix, then word prefix, then
    /// substring; reference stations break ties because they support curves.
    public func search(_ query: String, limit: Int = 60) -> [TideStation] {
        let tokens = Self.normalize(query).split(separator: " ").map(String.init)
        guard !tokens.isEmpty else { return [] }
        let scored: [(TideStation, Int)] = stations.compactMap { station in
            guard let key = searchKeys[station.id] else { return nil }
            var score = 0
            for token in tokens {
                guard let tokenScore = Self.score(token: token, key: key, station: station) else { return nil }
                score += tokenScore
            }
            if station.kind == .reference { score += 1 }
            return (station, score)
        }
        return scored
            .sorted { lhs, rhs in
                lhs.1 != rhs.1 ? lhs.1 > rhs.1 : lhs.0.displayName.title < rhs.0.displayName.title
            }
            .prefix(limit)
            .map(\.0)
    }

    static func score(token: String, key: String, station: TideStation) -> Int? {
        if station.id.lowercased() == token { return 100 }
        if key.hasPrefix(token) { return 30 }
        if key.contains(" " + token) { return 20 }
        if key.contains(token) { return 5 }
        return nil
    }

    static func searchKey(for station: TideStation) -> String {
        let stateName = USStates.names[station.state] ?? ""
        return normalize("\(station.noaaName) \(station.state) \(stateName) \(station.id)")
    }

    /// Lowercased, diacritic-free, punctuation collapsed to single spaces.
    static func normalize(_ text: String) -> String {
        let folded = text.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "en_US"))
        let mapped = folded.map { $0.isLetter || $0.isNumber ? $0 : " " }
        return String(mapped).split(separator: " ").joined(separator: " ")
    }
}

public enum USStates {
    public static let names: [String: String] = [
        "AK": "Alaska", "AL": "Alabama", "CA": "California", "CT": "Connecticut", "DC": "District of Columbia",
        "DE": "Delaware", "FL": "Florida", "GA": "Georgia", "GU": "Guam", "HI": "Hawaii", "LA": "Louisiana",
        "MA": "Massachusetts", "MD": "Maryland", "ME": "Maine", "MS": "Mississippi", "NC": "North Carolina",
        "NH": "New Hampshire", "NJ": "New Jersey", "NY": "New York", "OR": "Oregon", "PA": "Pennsylvania",
        "PR": "Puerto Rico", "RI": "Rhode Island", "SC": "South Carolina", "TX": "Texas", "VA": "Virginia",
        "VI": "U.S. Virgin Islands", "WA": "Washington",
    ]
}
